++ \u9009\u4e2d\u4efb\u52a1\u5b50\u96c6\u4e0a\u7684**\u6210\u529f\u7387\u663e\u8457\u9ad8\u4e8e**\u57fa\u7ebf\u7ec4\uff08\u5e73\u5747\u6210\u529f\u7387\u4e4b\u5dee > 0\uff0c\u5355\u4fa7\uff1b\u6216 \u2260 0\uff0c\u53cc\u4fa7\uff09\u3002\n- **\u63a2\u7d22\u6027\u5047\u8bbe**\uff08\u4e0d\u9884\u5148\u627f\u8bfa\u663e\u8457\u6027\uff09\uff1aCoT \u7684\u589e\u76ca\u5bf9**\u591a\u6b65\u9aa4\u3001\u89c4\u5212\u5bc6\u96c6\u578b**\u4efb\u52a1\uff08\u5982\u590d\u6742\u5de5\u4f5c\u6d41\uff09\u5927\u4e8e\u5bf9\u7b80\u5355\u5355\u6b65\u4efb\u52a1\uff1b\u4e0d\u540c CoT \u53d8\u4f53\uff08\u96f6\u6837\u672c\uff0f\u5c11\u6837\u672c\uff0f\u9690\u5f0f CoT\uff09\u4e4b\u95f4\u5b58\u5728\u589e\u76ca\u5dee\u5f02\u3002\n\n### 2. \u81ea\u53d8\u91cf\u64cd\u4f5c\u5316\uff08CoT \u63d0\u793a\u7684\u6709\u65e0\u53ca\u53d8\u4f53\uff09\n\u91c7\u7528**\u5355\u56e0\u5b50\u3001\u591a\u6c34\u5e73**\u53d7\u8bd5\u5185\uff08paired / within-task\uff09\u8bbe\u8ba1\uff0c\u6838\u5fc3\u56e0\u5b50\u4e3a\"\u63d0\u793a\u6761\u4ef6\"\uff1a\n- **A\uff08\u5bf9\u7167\uff0c\u57fa\u7ebf\uff09**\uff1a\u96f6\u6837\u672c\u76f4\u63a5\u63d0\u793a\u2014\u2014\u53ea\u7ed9\u4efb\u52a1\u63cf\u8ff0\u4e0e\u53ef\u7528\u52a8\u4f5c\uff0c\u8981\u6c42\u4ee3\u7406\u76f4\u63a5\u884c\u52a8\uff0c**\u4e0d\u542b\u4efb\u4f55\u63a8\u7406\u6307\u5f15**\u3002\n- **B\uff08\u5904\u74061\uff0c\u96f6\u6837\u672c CoT\uff09**\uff1a\u5728\u884c\u52a8\u524d\u663e\u5f0f\u8981\u6c42\"\u9010\u6b65\u63a8\u7406\"\uff08\u5982 \"Let's think step by step\" \u6216\u7b49\u4ef7\u4e2d\u6587\u6307\u4ee4\uff09\uff0c\u63a8\u7406\u6587\u672c\u4f5c\u4e3a\u9644\u52a0\u8f93\u51fa\u540e\u63a5\u884c\u52a8\u3002\n- **C\uff08\u5904\u74062\uff0c\u5c11\u6837\u672c CoT\uff09**\uff1a\u5728\u7cfb\u7edf/\u7528\u6237\u63d0\u793a\u4e2d\u8ffd\u52a0 2\u20133 \u4e2a\"\u4efb\u52a1\u63cf\u8ff0\u2192\u63a8\u7406\u8f68\u8ff9\u2192\u6b63\u786e\u884c\u52a8\"\u793a\u8303\u6837\u4f8b\uff08exemplars\uff09\u3002\n- **D\uff08\u53ef\u9009\u9879\uff0c\u5904\u74063\uff0c\u9690\u5f0f/\u5185\u90e8 CoT\uff09**\uff1a\u63a8\u7406\u5728\u5185\u90e8\u5b8c\u6210\u3001\u4e0d\u628a\u63a8\u7406\u6587\u672c\u66b4\u9732\u7ed9\u73af\u5883\uff08\u7528\u4e8e\u5206\u79bb\"\u6587\u672c\u53ef\u89c1\u6027\"\u4e0e\"\u63a8\u7406\u673a\u5236\"\u4e24\u4e2a\u7ef4\u5ea6\uff09\u3002\n- **E\uff08\u53ef\u9009\u9879\uff0c\u5bf9\u7167 B'\uff09**\uff1a\u5c11\u6837\u672c**\u65e0** CoT\uff08\u4e0e C \u76f8\u540c\u6570\u91cf\u7684\u793a\u8303\u4f46\u793a\u8303\u4e2d\u4e0d\u542b\u63a8\u7406\uff09\u2014\u2014\u7528\u4e8e\u628a\"\u66f4\u591a\u793a\u8303\"\u4e0e\"CoT \u63a8\u7406\"\u7684\u6548\u679c\u533a\u5206\u5f00\u3002\n\n> \u8be5\u56e0\u5b50\u7ed3\u6784\u5929\u7136\u652f\u6301\u4e24\u4e2a\u5bf9\u6bd4\uff1a**\u4e3b\u6548\u5e94**\uff08\u542b CoT vs \u4e0d\u542b CoT \u7684 B/C/D/B' \u4e0e A \u7684\u7ec4\u5408\u5bf9\u6bd4\uff09\u4e0e**\u53d8\u4f53\u95f4\u5bf9\u6bd4**\uff08B vs C vs D\uff1bC vs B'\uff09\u3002\n\n### 3. \u56e0\u53d8\u91cf\u64cd\u4f5c\u5316\u4e0e\u6307\u6807\u5b9a\u4e49\n- **\u4e3b\u6307\u6807\uff08Primary\uff09**\uff1a**\u4efb\u52a1\u6210\u529f\u7387\uff08Success Rate, SR\uff09** = \u5f97\u5206\u4e3a\"\u901a\u8fc7\"\u7684\u4efb\u52a1\u5b9e\u4f8b\u5360\u6bd4\u3002\u901a\u8fc7\u5224\u5b9a\u53d6 WorkArena++ \u8bc4\u5206\u5668\u5206\u6570 \u2265 \u9884\u6ce8\u518c\u9608\u503c\uff08\u5982\u8fde\u7eed\u5956\u52b1 \u2265 0.9 \u6216\u7b49\u4ef7\u4e8c\u503c\u5316\uff09\uff0c\u9608\u503c\u4e8b\u5148\u56fa\u5b9a\u3002\n- **\u8f85\u52a9\u6307\u6807\uff08Secondary\uff09**\uff1a\n  - \u5e73\u5747\u8fde\u7eed\u6027\u5956\u52b1\u5206\u6570\uff08judge \u8f93\u51fa\uff0c[0,1] \u8fde\u7eed\u5206\uff09\uff1b\n  - \u4efb\u52a1\u5b8c\u6210\u7387\uff08\u5230\u8fbe\u7ec8\u6b62\u72b6\u6001\u7684\u6bd4\u4f8b\uff0c\u4e0d\u8bba\u5bf9\u9519\uff09\uff1b\n  - \u6b65\u9aa4\u6548\u7387\uff1a\u6210\u529f\u4efb\u52a1\u7684\u5e73\u5747\u52a8\u4f5c\u6b65\u6570\u4e0e**\u6b65\u6570\u4e2d\u4f4d\u6570**\uff1b\n  - \u6807\u8bb0/\u6210\u672c\u6548\u7387\uff1a\u6bcf\u4efb\u52a1\u5e73\u5747\u603b token \u6570\u4e0e\u4f30\u7b